<?php declare(strict_types=1); namespace Neok\Pay\Laravel\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Event; use Neok\Pay\DTO\WebhookEvent; use Neok\Pay\Laravel\Events\{PaymentSucceeded,UnknownWebhookReceived}; use Symfony\Component\HttpFoundation\Response;
final class WebhookController { public function __invoke(Request $request): Response {$event=$request->attributes->get('neokpay.webhook_event');if(!$event instanceof WebhookEvent)return response()->json(['error'=>'Invalid NEOK Pay webhook.'],400);if(config('neokpay.webhook.deduplicate')&&!Cache::add('neokpay:webhook:'.$event->id,true,now()->addDay()))return response()->noContent();if($event->isPaymentSucceeded())Event::dispatch(new PaymentSucceeded($event));else Event::dispatch(new UnknownWebhookReceived($event));return response()->noContent();} }
